INSERT INTO products (id, category_id, name, name_th, description, price_satang, image_url, is_available, sort_order) VALUES
('a0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 'Crispy Catfish with Green Mango Salad', 'ยำปลาดุกฟูสูตรโบราณ (ชุดมาตรฐาน)', 'เนื้อปลาดุกย่างแกะก้าง ทอดฟูกรอบสีทอง เสิร์ฟพร้อมน้ำยำมะม่วงสับรสแซ่บ', 12000, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80', true, 1),
('a0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 'Crispy Catfish Salad - Family Giant Size', 'ยำปลาดุกฟูจานยักษ์ (เซ็ตครอบครัว)', 'ปลาดุกฟูขนาดใหญ่จุใจ เหมาะสำหรับทาน 3-4 ท่าน น้ำยำมะม่วงเข้มข้น 2 ถ้วย', 22000, 'https://images.unsplash.com/photo-1559847844-5315695dadae?auto=format&fit=crop&w=600&q=80', true, 2),
('a0000000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000002', 'Southern Yellow Sour Curry with Sea Bass on Rice', 'ข้าวแกงส้มปลากะพงยอดมะพร้าวอ่อน', 'แกงส้มใต้รสจัดจ้าน เปรี้ยวนำ เผ็ดร้อนจากพริกแกงสด เสิร์ฟคู่ข้าวหอมมะลิ', 7500, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=600&q=80', true, 1),
('a0000000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000002', 'Spicy Minced Pork Curry on Rice (Kua Kling)', 'ข้าวคั่วกลิ้งหมูสับใบยี่หร่า', 'คั่วกลิ้งแห้งหอมสมุนไพรใต้ เผ็ดร้อนลึก ทานคู่ผักสดกรอบและข้าวสวย', 7000, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=600&q=80', true, 2),
('a0000000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000002', 'Pork Belly Braised in Sweet Brown Gravy (Moo Hong)', 'ข้าวหมูฮ้องภูเก็ตทรงเครื่อง', 'หมูสามชั้นเคี่ยวซีอิ๊วดำ พริกไทย และกระเทียมจนเปื่อยนุ่มละลายในปาก', 8500, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=600&q=80', true, 3),
('a0000000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000003', 'Spicy Tom Yum Soup with River Prawns', 'ต้มยำกุ้งแม่น้ำน้ำข้นหม้อไฟ', 'กุ้งแม่น้ำตัวโต มันกุ้งเยิ้ม ต้มยำรสเข้มข้น หอมสมุนไพรสด', 18000, 'https://images.unsplash.com/photo-1555126634-323283e090fa?auto=format&fit=crop&w=600&q=80', true, 1),
('a0000000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000004', 'Crispy Deep-Fried Fish Cakes', 'ทอดมันปลากรายแท้สูตรโบราณ', 'เนื้อปลากรายนวดฟูเหนียวนุ่ม เด้งสู้ฟัน ไร้แป้ง เสิร์ฟคู่น้ำจิ้มอาจาด', 9000, 'https://images.unsplash.com/photo-1541544741938-0af808871cc0?auto=format&fit=crop&w=600&q=80', true, 1),
('a0000000-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000005', 'Traditional Thai Iced Milk Tea', 'ชาไทยเย็นเข้มข้นสูตรโบราณ', 'ชาไทยหอมกรุ่น นมสดแท้ หวานมันกลมกล่อม', 4500, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?auto=format&fit=crop&w=600&q=80', true, 1),
('a0000000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000005', 'Iced Fresh Longan Drink', 'น้ำลำไยสดเนื้อแน่นภูพาน', 'น้ำลำไยต้มหวานละมุน พร้อมเนื้อลำไยลูกโต สดชื่นคลายร้อน', 4500, 'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?auto=format&fit=crop&w=600&q=80', true, 2)
